CREATE OR REPLACE FUNCTION premature_resolution_block()
RETURNS TRIGGER AS $$
DECLARE
    iii numeric;
BEGIN
    -- Only check when trying to resolve
    IF NEW.resstat = 'Resolved' AND (OLD.resstat IS NULL OR OLD.resstat != 'Resolved') THEN
        -- Calculate Investigation Intensity Index for the linked investigation
        SELECT (0.6 * id.behansc + 0.4 * id.netansc) INTO iii
        FROM investigationdetails id
        WHERE id.invdetreg = NEW.invdetref;

        -- Block resolution if III exceeds threshold of 75
        IF iii > 75 THEN
            RAISE EXCEPTION 'Resolution blocked: Premature Resolution Block condition met. Investigation Intensity Index (%).', iii;
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_premature_resolution_block ON enforcementactions;

CREATE TRIGGER trg_premature_resolution_block
BEFORE UPDATE ON enforcementactions
FOR EACH ROW
EXECUTE FUNCTION premature_resolution_block();
